    <style>
        :root{--ink:#172033;--muted:#718096;--brand:#5b5bd6;--line:#e7eaf0;--canvas:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.topbar{background:#fff;border-bottom:1px solid var(--line)}.page-shell{width:100%;padding:30px 24px 50px}.brand-mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,var(--brand),#8b5cf6);display:grid;place-items:center;color:#fff}.subtext{font-size:.78rem;color:var(--muted)}.eyebrow{color:var(--brand);font-size:.73rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.page-title{font-weight:750;letter-spacing:-.035em}.panel{position:relative;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 10px 35px rgba(32,41,64,.05)}.form-control,.form-select{border-color:var(--line);border-radius:11px;min-height:44px}.form-control:focus,.form-select:focus{border-color:#aaaaf1;box-shadow:0 0 0 .2rem #5b5bd615}.btn-brand{background:var(--brand);border-color:var(--brand);color:#fff}.btn-brand:hover{background:#4848bf;color:#fff}.table{min-width:780px;margin:0}.table th{background:#fafbfc;color:#697386;font-size:.7rem;text-transform:uppercase;letter-spacing:.08em;padding:14px 18px}.table td{padding:15px 18px;vertical-align:middle;border-color:#eff1f5}.avatar{width:38px;height:38px;border-radius:11px;background:#ededff;color:var(--brand);display:grid;place-items:center;font-weight:800}.source-pill{background:#e8f8f1;color:#087d55;border-radius:999px;padding:5px 9px;font-size:.7rem;font-weight:700}.soft-btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:10px;padding:.55rem .8rem;font-weight:600}.pagination{margin:0}.page-link{border:0;color:#596274;border-radius:8px!important;margin:0 2px}.page-item.active .page-link{background:var(--brand)}.registration-search-wrap{position:relative}.registration-results{position:absolute;z-index:1100;left:0;right:0;top:50px;background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 18px 45px rgba(32,41,64,.18);max-height:310px;overflow:auto}.registration-result{display:flex;width:100%;align-items:center;gap:11px;padding:12px 14px;border:0;border-bottom:1px solid #eff1f5;background:#fff;text-align:left}.registration-result:hover,.registration-result:focus{background:#f6f6ff}.result-icon{width:35px;height:35px;display:grid;place-items:center;border-radius:10px;background:#ededff;color:var(--brand);flex:none}.selected-registration{background:#f0fbf6;border:1px solid #bce7d4;border-radius:11px;padding:10px 12px}.panel-loading{position:absolute;inset:0;background:#ffffffc7;z-index:10;display:grid;place-items:center}.toast-box{position:fixed;top:18px;right:18px;z-index:2000;max-width:min(390px,calc(100vw - 36px))}
    </style>
</head>
