    <div class="row g-3 mt-1"><div class="col-12"><label class="form-label fw-semibold">Name</label><input class="form-control person-name" name="name" value="{{ old('name') }}" required></div><div class="col-12"><label class="form-label fw-semibold">Phone number</label><input class="form-control person-phone" name="phone" value="{{ old('phone') }}" required></div><div class="col-12"><label class="form-label fw-semibold">Possible time of departure <span class="text-secondary fw-normal">(optional)</span></label><input type="datetime-local" class="form-control" name="possible_departure_at" value="{{ old('possible_departure_at') }}"></div><div class="col-12"><label class="form-label fw-semibold">Notes <span class="text-secondary fw-normal">(optional)</span></label><textarea class="form-control" rows="3" name="notes">{{ old('notes') }}</textarea></div></div>
