<div class="modal fade" id="editModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form id="editForm" class="modal-content border-0 rounded-4" method="POST">@csrf @method('PATCH')<div class="modal-header"><h5 class="modal-title">Edit details</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-danger d-none form-error"></div><div class="mb-3"><label class="form-label fw-semibold">Name</label><input class="form-control" name="name" required></div><div class="mb-3"><label class="form-label fw-semibold">Phone number</label><input class="form-control" name="phone" required></div><div class="mb-3"><label class="form-label fw-semibold">Possible time of departure</label><input type="datetime-local" class="form-control" name="possible_departure_at"></div><div><label class="form-label fw-semibold">Notes</label><textarea class="form-control" rows="3" name="notes"></textarea></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-brand submit-button">Save changes</button></div></form></div></div>

<div id="toastBox" class="toast-box"></div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const indexUrl=@json(route('special-accommodations.index')), registrationSearchUrl=@json(route('special-accommodations.registration-search')), csrf=document.querySelector('meta[name="csrf-token"]').content;
const addModal=bootstrap.Modal.getOrCreateInstance('#addModal'), editModal=bootstrap.Modal.getOrCreateInstance('#editModal');
let registrationTimer, listTimer, searchController, listController;
const escapeHtml=value=>{const element=document.createElement('div');element.textContent=value??'';return element.innerHTML};

async function request(url,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(url,{...options,signal:options.signal||controller.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest',...(options.headers||{})}}),type=response.headers.get('content-type')||'',payload=type.includes('application/json')?await response.json():await response.text();if(!response.ok){const error=new Error(typeof payload==='object'?(Object.values(payload.errors||{}).flat()[0]||payload.message):'The server returned an unexpected response.');error.validation=response.status===422;throw error}return payload}catch(error){if(error.name==='AbortError')throw new Error('The request timed out. Please try again.');if(error instanceof TypeError)throw new Error('No network connection. Check your internet and try again.');throw error}finally{clearTimeout(timeout)}}
function toast(message,type='success'){document.getElementById('toastBox').innerHTML=`<div class="alert alert-${type} shadow-lg border-0 alert-dismissible fade show"><i class="bi bi-${type==='success'?'check-circle-fill':'exclamation-triangle-fill'} me-2"></i>${escapeHtml(message)}<button class="btn-close" data-bs-dismiss="alert"></button></div>`}
function setLoading(loading){const panel=document.getElementById('registerPanel');panel.querySelector('.panel-loading')?.remove();if(loading)panel.insertAdjacentHTML('beforeend','<div class="panel-loading"><div class="spinner-border text-primary"></div></div>')}
async function refreshList(url=location.href,push=true){listController?.abort();listController=new AbortController();setLoading(true);try{const response=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest'},signal:listController.signal});if(!response.ok)throw new Error('Could not refresh the accommodation register.');const html=await response.text(),documentCopy=new DOMParser().parseFromString(html,'text/html'),panel=documentCopy.getElementById('registerPanel');if(!panel)throw new Error('The server returned an invalid page.');document.getElementById('registerPanel').replaceWith(panel);if(push)history.replaceState({},'',url)}catch(error){if(error.name!=='AbortError')toast(error.message,'danger')}finally{setLoading(false)}}

document.getElementById('registrationSearch').addEventListener('input',event=>{clearTimeout(registrationTimer);searchController?.abort();const term=event.target.value.trim(),results=document.getElementById('registrationResults');document.getElementById('registrationId').value='';document.getElementById('selectedRegistration').classList.add('d-none');if(term.length<2){results.classList.add('d-none');results.innerHTML='';return}results.classList.remove('d-none');results.innerHTML='<div class="text-center py-3"><span class="spinner-border spinner-border-sm text-primary"></span></div>';registrationTimer=setTimeout(async()=>{searchController=new AbortController();try{const payload=await request(`${registrationSearchUrl}?q=${encodeURIComponent(term)}`,{signal:searchController.signal});results.innerHTML=payload.results.length?payload.results.map(person=>`<button type="button" class="registration-result" data-id="${person.id}" data-name="${escapeHtml(person.fullname)}" data-phone="${escapeHtml(person.phone)}"><span class="result-icon"><i class="bi bi-person-check-fill"></i></span><span><strong class="d-block">${escapeHtml(person.fullname)}</strong><span class="subtext"><i class="bi bi-telephone me-1"></i>${escapeHtml(person.phone||'No phone')}</span></span></button>`).join(''):'<div class="text-center text-secondary py-4"><i class="bi bi-search d-block mb-1"></i>No available confirmed registration found.</div>'}catch(error){if(error.name!=='AbortError')results.innerHTML=`<div class="text-center text-danger py-3">${escapeHtml(error.message)}</div>`}},250)});
document.getElementById('registrationResults').addEventListener('click',event=>{const result=event.target.closest('.registration-result');if(!result)return;const form=document.getElementById('addForm');form.elements.conference_registration_id.value=result.dataset.id;form.elements.name.value=result.dataset.name;form.elements.phone.value=result.dataset.phone;document.getElementById('registrationSearch').value=result.dataset.name;document.getElementById('registrationResults').classList.add('d-none');const selected=document.getElementById('selectedRegistration');selected.innerHTML=`<i class="bi bi-patch-check-fill text-success me-2"></i><strong>${escapeHtml(result.dataset.name)}</strong><span class="subtext ms-2">${escapeHtml(result.dataset.phone)}</span>`;selected.classList.remove('d-none')});

document.addEventListener('submit',async event=>{if(event.target.id==='registerSearchForm'){event.preventDefault();const params=new URLSearchParams(new FormData(event.target));await refreshList(`${indexUrl}?${params}`);return}if(!event.target.matches('#addForm,#editForm,.delete-form'))return;event.preventDefault();const form=event.target,isDelete=form.classList.contains('delete-form');if(isDelete&&!confirm(`Remove ${form.dataset.name} from special accommodation?`))return;const button=form.querySelector('button[type="submit"],button:not([type])'),error=form.querySelector('.form-error'),data=new FormData(form);if(error)error.classList.add('d-none');if(button){button.disabled=true;button.dataset.label=button.innerHTML;button.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Saving…'}try{const payload=await request(form.action,{method:'POST',headers:{'X-CSRF-TOKEN':csrf},body:data});if(form.id==='addForm'){addModal.hide();form.reset();document.getElementById('selectedRegistration').classList.add('d-none')}if(form.id==='editForm')editModal.hide();await refreshList(location.href,false);toast(payload.message)}catch(exception){if(error&&exception.validation){error.textContent=exception.message;error.classList.remove('d-none')}else toast(exception.message,'danger')}finally{if(button){button.disabled=false;button.innerHTML=button.dataset.label}}});
document.addEventListener('click',event=>{const edit=event.target.closest('.edit-button');if(edit){const form=document.getElementById('editForm');form.action=edit.dataset.url;form.elements.name.value=edit.dataset.name;form.elements.phone.value=edit.dataset.phone;form.elements.possible_departure_at.value=edit.dataset.departure||'';form.elements.notes.value=edit.dataset.notes||'';form.querySelector('.form-error').classList.add('d-none');return}const page=event.target.closest('#registerPanel .pagination a');if(page){event.preventDefault();refreshList(page.href);return}const clear=event.target.closest('.clear-search');if(clear){event.preventDefault();refreshList(clear.href)}});
document.addEventListener('input',event=>{if(!event.target.matches('#registerSearchForm input[name="search"]'))return;clearTimeout(listTimer);listTimer=setTimeout(()=>{const params=new URLSearchParams(new FormData(event.target.form));refreshList(`${indexUrl}?${params}`)},350)});
document.addEventListener('click',event=>{if(!event.target.closest('.registration-search-wrap'))document.getElementById('registrationResults').classList.add('d-none')});
window.addEventListener('offline',()=>toast('You are offline. Changes cannot be saved.','danger'));window.addEventListener('online',()=>toast('Your connection is back.'));
</script>
</body></html>
